<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';if(empty($_SESSION['admin_id']))redirect('index.php');require_once dirname(__DIR__).'/private/operations.php';require_once dirname(__DIR__).'/private/ui.php';
$id=max(0,(int)($_GET['id']??0));
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();try{$id=opsSaveWorker($pdo,(int)$_SESSION['admin_id'],$_POST,$id);$_SESSION['app_notice']='Zuordnung gespeichert. Kein Benutzerkonto erstellt.';}catch(Throwable $e){gszUiError($e);}redirect('workers.php'.($id?'?id='.$id:''));}
$rows=[];$w=[];try{opsRequire($pdo);$rows=$pdo->query('SELECT * FROM operations_workers ORDER BY active DESC,name,id LIMIT 200')->fetchAll();if($id){$q=$pdo->prepare('SELECT * FROM operations_workers WHERE id=?');$q->execute([$id]);$w=$q->fetch()?:throw new RuntimeException('Zuordnung nicht gefunden.');}}catch(Throwable $e){gszUiError($e);}gszPageStart('Mitarbeiter und Subunternehmer');
?><p>Einfache organisatorische Zuordnung ohne Benutzerkonten, Tracking oder Pflichtnachweise. Die Zeitplanung bleibt eine Planung für den Inhaber; keine parallele Personal-/Kapazitätsplanung.</p><p><a href="workers.php?new=1">Neue Zuordnung</a> · <a href="planner.php">Heute</a></p><?php foreach($rows as $row):?><p><a href="?id=<?=(int)$row['id']?>"><?=e($row['name'])?></a> · <?=$row['kind']==='employee'?'Mitarbeiter':'Subunternehmer'?> · <?=$row['active']?'Aktiv':'Inaktiv'?></p><?php endforeach?>
<?php if($w||isset($_GET['new'])):?><section class="card"><form method="post"><?php gszFields('save');?><input type="hidden" name="row_version" value="<?=(int)($w['row_version']??0)?>"><label>Name<input name="name" maxlength="190" required value="<?=e($w['name']??'')?>"></label><label>Art<select name="kind"><option value="employee">Mitarbeiter</option><option value="subcontractor" <?=($w['kind']??'')==='subcontractor'?'selected':''?>>Subunternehmer</option></select></label><label>E-Mail<input name="email" type="email" maxlength="190" value="<?=e($w['email']??'')?>"></label><label>Telefon<input name="phone" maxlength="80" value="<?=e($w['phone']??'')?>"></label><label>Notizen<textarea name="notes" maxlength="5000"><?=e($w['notes']??'')?></textarea></label><label><input type="checkbox" name="active" value="1" <?=!isset($w['active'])||$w['active']?'checked':''?>> Aktiv</label><button>Zuordnung speichern</button></form></section><?php endif?><?php gszPageEnd();?>
